 function flushOutput(){sentencePractice?.flush();batchPractice?.flush();batchPractice?.cancel(false);}
 function guidedBatchText(){sentencePractice.flush();if(!sentencePractice.ensureState())return '';const answers=sentencePractice.active?.draft.answers||{};if(!Object.values(answers).some(text=>text.trim()))return '';const lines=[],target=sentencePractice.target(),oldWord=sentencePractice.oldWord(),oldPhrase=sentencePractice.oldPhrase();if(target)lines.push('目标词：'+target.word);if(oldWord)lines.push('旧词：'+oldWord.word);if(oldPhrase)lines.push('旧用法：'+oldPhrase.phrase);for(const [kind,label] of [['affirmative','原句'],['negative','否定句'],['yesno','一般疑问句'],['wh','特殊疑问句'],['combined','旧知综合句']])if(answers[kind]?.trim())lines.push(label+'：'+answers[kind]);return lines.join('\n');}
 function lessonProgress(id){const l=lessons.find(x=>x.id===id),cards=l?StudyReview.cardsForLessons([l]):[];return StudyLearningProgress.describe(safeRecord(id),{dueCount:StudyReview.queue(data.review,cards).length});}
 function startRetest(id){if(!isPilotLesson(lessons.find(l=>l.id===id))||!lessonProgress(id).canRetest){toast('复测在上次正式练习至少24小时后开放。');return;}selectLesson(id);practice={mode:'mixed',answers:{},submitted:false,isRetest:true};setTab('practice');mobileShell?.focusReader();}
