 function saveOutputRecord(result){const lesson=outputContext||current,old=safeRecord(lesson.id);data.records[lesson.id]={...StudyLearningProgress.recordPractice(old,{score:result.score,mode:result.mode,now:Date.now(),isRetest:false}),title:lesson.title,book:lesson.book,output:{mode:result.mode,score:result.score,answer:String(result.details?.answer||'').slice(0,10000)}};const saved=persist();if(saved&&lessons.some(l=>l.id===lesson.id))enrollLessonReview(lesson);toast(saved?'练习反馈已生成，记录已保存。':'反馈已生成，请导出数据备份。');return saved;}
 function renderGame(){if(game)$('#game-view').innerHTML=game.render(selectedBook);}
 async function shareSite(){const url=location.href.split('#')[0];try{if(navigator.share){await navigator.share({title:'知新 · 新概念英语学习室',text:'一起读课文、记单词、闯关练英语。',url});return;}if(navigator.clipboard){await navigator.clipboard.writeText(url);toast('网站链接已复制，可以分享给朋友。');return;}}catch(e){if(e.name==='AbortError')return;}openDialog('分享学习室',`<p>复制下面的链接，就能在手机、平板和电脑上打开。</p><label class="form-field">网站链接<input value="${E(url)}" readonly id="share-url"></label>`);$('#share-url').select();}
 function showSharingNote(){openDialog('分享与转载说明','<p>欢迎分享本站链接。本站自编训练题和界面允许转载，请标明“来自知新学习室”并保留来源链接。</p><p>教材 PDF 和其他第三方资料保留原有版权与许可，本说明不为它们授予额外的转载权利。</p><p>内置单词音频为 Microsoft Zira Desktop 美式合成语音；已另行接入用户提供的部分课文文件音频。</p><p class="small-note">学习记录、生词本和自行导入的资料只保存在当前浏览器，不会公开给其他访问者。</p>');}
 function renderLibrary(){
  const rows=window.STUDY_LIBRARY||[],matching=rows.filter(f=>!query||f.title.toLowerCase().includes(query));
  $('#library-view').innerHTML=`<div class="view-heading"><div><h2>我的教材资料</h2><p>文字资料 ${rows.length} 份 · ${rows.reduce((n,f)=>n+f.pages,0)} 页 · 来自你的本地文件</p></div><button class="button" id="open-import">${icon('upload')}导入课文与音频</button></div><div class="library-notice">${icon('book')}教材笔记支持文字学习；新增三册扫描识别底稿需逐课校对。已校对正文可在学习空间进行阅读与输出训练。</div>${[selectedBook,...[1,2,3,4,0].filter(b=>b!==selectedBook)].map(book=>{const group=matching.filter(f=>f.book===book);return `<section class="library-group"><h3>${book?BOOKS[book-1].name+' · '+BOOKS[book-1].full:'通用学习资料'}<span>${group.length} 份</span></h3>${group.length?group.map(f=>`<div class="document-row"><span class="document-icon">${icon('file')}</span><div class="document-info"><strong>${E(f.title)}</strong><small>${f.ocrDraft?'扫描识别待校对':'笔记文字版'} · ${f.pages} 页 · ${(f.bytes/1024/1024).toFixed(1)} MB</small></div><button class="button" data-document="${E(f.id)}">${f.ocrDraft?'识别文字':'文字学习'}${icon('right')}</button><a class="icon-button" href="${E(f.url)}" download="${E(f.title)}.pdf" aria-label="下载 ${E(f.title)}">${icon('download')}</a></div>`).join(''):`<div class="library-empty">${query?'没有匹配的资料':book===4?'第四册扫描资料已收到，正在逐课识别校对。已校对课文可在学习空间阅读。':'这一册暂时没有已下载的资料。'}</div>`}</section>`;}).join('')}<p class="small-note">已去除重复文件。下载中的临时文件未接入，教材资料保留各自的原有版权说明。</p>`;
 }
 function openDocument(id,index=null){flushOutput();closeDialog();view='library';audio.pause();renderAll();textReader.open(id,index);}

 function openResources(){const library=window.STUDY_LIBRARY||[];openDialog('教材与学习资料',`<p class="usage-note">选择官方资源，或导入已有的课文和音频，和站内练习一起学习。</p>${library.length?`<h3>已接入的教材资料</h3><button class="button" id="open-library">前往我的教材资料</button><div class="record-list">${library.map(f=>`<a class="resource-link" href="${E(f.url)}" target="_blank" rel="noopener">${icon('file')}<span>${E(f.title)}<small>第 ${f.book} 册 · ${E(f.kind||'PDF')}</small></span>${icon('external')}</a>`).join('')}</div>`:''}<section class="usage-card"><h3>外研社 · 新概念英语智慧版</h3><p>出版社说明：智慧版正版图书激活后，可在“外研 U 学”获取配套数字学习资源，包括跟读单词、单词练习与课文听读。</p><a class="button" href="https://www.fltrp.com/ebook/jcjyyjzx/2023_jcjyjxzy/files/basic-html/page62.html" target="_blank" rel="noopener">查看官方资源说明${icon('external')}</a></section><section class="usage-card"><h3>语法与词汇配套学习</h3><p>外研社介绍了《新概念英语词汇在用》《新概念英语语法在用》等配套学习产品，可结合四册课程复习。</p><a class="resource-link" href="https://www.fltrp.com/c/2025-09-26/539371.shtml" target="_blank" rel="noopener">查看出版社介绍${icon('external')}</a></section><p class="small-note">资料核对：2026-10-24。外部资源的可用性及激活要求以出版社为准。本站为独立学习工具；当前文字内容来自已接入的新概念课堂笔记与练习，并非完整四册教材课文。内置音频为 Microsoft Zira 美式合成音频；导入课文可使用设备语音或自有音频。</p>`,`<button class="button primary" id="resources-import">${icon('upload')}导入我的资料</button>`);}
 function openImport(){openDialog('导入课文与音频',`<p class="small-note">把自己的资料放进学习室。导入的课文和音频只保存在当前浏览器。</p><div class="form-grid"><label class="form-field">所属分册<select id="import-book">${BOOKS.map(b=>`<option value="${b.n}" ${b.n===selectedBook?'selected':''}>${b.name} · ${b.full}</option>`).join('')}</select></label><label class="form-field">课号<input id="import-number" type="number" min="1" max="999" value="1"></label></div><label class="form-field">课文标题<input id="import-title" placeholder="如：Lesson 1 · 我的课文" maxlength="150"></label><label class="form-field">选择课文文件（TXT / LRC / JSON）<input id="import-text-file" type="file" accept=".txt,.lrc,.json"></label><label class="form-field">或粘贴英文课文<textarea id="import-text" rows="5" placeholder="每行一个段落；LRC 时间标签会自动识别。"></textarea></label><label class="form-field">配套音频（可选，单文件不超过 50MB）<input id="import-audio" type="file" accept="audio/*,.mp3,.m4a,.wav,.ogg"></label><label class="check-label"><input type="checkbox" id="audio-only">仅把音频绑定到当前课文</label><p class="small-note">JSON 支持批量课文、翻译、词汇、习惯用法和题库。学习数据备份也可从这里恢复。批量导入时请单独为各课绑定音频。</p><button class="resource-link" id="download-template">下载 JSON 资料模板${icon('download')}</button><p class="result-explanation hidden" id="import-error" role="alert"></p>`,`<button class="button" id="cancel-import">取消</button><button class="button primary" id="confirm-import">${icon('upload')}导入并开始学习</button>`);}
 async function confirmImport(){const button=$('#confirm-import');button.disabled=true;const errorEl=$('#import-error');try{const file=$('#import-text-file').files[0],audioFile=$('#import-audio').files[0],only=$('#audio-only').checked;if(audioFile&&audioFile.size>50*1024*1024)throw new Error('音频超过 50MB，请压缩或分课导入。');if(only){if(!audioFile)throw new Error('请选择要绑定的音频文件。');const targetLesson=current;await StudyFiles.putAudio(targetLesson.id,audioFile);if(current.id===targetLesson.id)audio.setLesson(targetLesson,audioFile);closeDialog();toast('音频已绑定到当前课文，并保存在此浏览器。');return;}
  const text=file?await file.text():$('#import-text').value;if(!text.trim())throw new Error('请选择课文文件，或粘贴英文课文。');let rows;
  if(file?.name.toLowerCase().endsWith('.json')||!file&&/^[{[]/.test(text.trim())&&!/^\[(?:\d{1,3}:|(?:ti|ar|al|by|offset):)/i.test(text.trim())){let raw;try{raw=JSON.parse(text);}catch{throw new Error('JSON 格式不正确。');}if(raw.format==='zhixin-backup-v1'){restoreBackup(raw);closeDialog();await selectLesson(current.id);toast('学习备份已恢复；本地音频需要单独导入。');return;}if(file&&file.size>5*1024*1024)throw new Error('课文文件超过 5MB，请按册或按课拆分；学习备份不受此限制。');rows=StudyCore.parseLessonJSON(text);}else{if(file&&file.size>5*1024*1024)throw new Error('课文文件超过 5MB，请按册或按课拆分。');const title=$('#import-title').value.trim()||file?.name.replace(/\.[^.]+$/,'');if(!title)throw new Error('请填写课文标题。');rows=[StudyCore.fromText(text,{book:Number($('#import-book').value),number:Number($('#import-number').value),title})];}
  if(audioFile&&rows.length!==1)throw new Error('批量课文请先导入，再逐课绑定配套音频。');if(audioFile)await StudyFiles.putAudio(rows[0].id,audioFile);data.imported.push(...rows);lessons=[...window.LESSONS,...data.imported];if(!persist()){data.imported.splice(-rows.length);lessons=[...window.LESSONS,...data.imported];throw new Error('存储空间不足，未导入课文。请先备份资料。');}closeDialog();await selectLesson(rows[0].id);toast(`已导入 ${rows.length} 篇课文。`);
 }catch(e){errorEl.textContent=e.message||'导入未成功，请检查文件。';errorEl.classList.remove('hidden');}finally{if(button.isConnected)button.disabled=false;}}
 function restoreBackup(raw){if(!raw.data||!Array.isArray(raw.data.words))throw new Error('备份缺少生词数据。');let restored=[];if(raw.data.imported?.length)restored=StudyCore.parseLessonJSON(JSON.stringify(raw.data.imported)).map((l,i)=>({...l,id:/^[\w-]+$/.test(raw.data.imported[i].id)?raw.data.imported[i].id:l.id}));const previous={data:{...data},lessons,current};data.words=raw.data.words.slice(0,5000).filter(v=>v&&typeof v.word==='string');data.records=raw.data.records&&typeof raw.data.records==='object'?raw.data.records:{};batchPractice?.cancel(false);data.sentenceBatch=raw.data.sentenceBatch&&typeof raw.data.sentenceBatch==='object'&&!Array.isArray(raw.data.sentenceBatch)?raw.data.sentenceBatch:{};data.sentenceBatches=raw.data.sentenceBatches&&typeof raw.data.sentenceBatches==='object'&&!Array.isArray(raw.data.sentenceBatches)?raw.data.sentenceBatches:{};data.sentencePractice=raw.data.sentencePractice&&typeof raw.data.sentencePractice==='object'&&!Array.isArray(raw.data.sentencePractice)?raw.data.sentencePractice:{};data.game=raw.data.game&&typeof raw.data.game==='object'?raw.data.game:{xp:0,levels:{},daily:{}};data.imported=restored;lessons=[...window.LESSONS,...data.imported];current=lessons.find(l=>l.id===current?.id)||lessons[0];data.review=StudyReview.enroll(StudyReview.sanitize(raw.data.review),StudyReview.cardsForLessons(lessons.filter(l=>StudyReview.hasStudied(safeRecord(l.id)))));if(!persist()){Object.assign(data,previous.data);lessons=previous.lessons;current=previous.current;throw new Error('无法保存备份，原数据已保留。');}sentencePractice?.reloadFromStorage();batchPractice?.reloadFromStorage();}
 function review(id){const r=safeRecord(id),l=lessons.find(x=>x.id===id),bank=window.StudyKnowledge?.bank;openDialog('错题回顾',(r.wrong||[]).map((w,i)=>{const q=bank?.hasLesson(id)?bank.questionsForLesson(id).find(q=>(w.conceptId&&q.conceptId===w.conceptId)||q.question===w.question):null;if(bank?.hasLesson(id)&&!q)return '<section class="usage-card"><h3>'+E(w.question)+'</h3><p>这道历史错题暂无已核对答案，请回到本课最新练习。</p></section>';return '<section class="usage-card"><h3>'+E(q?.question||w.question)+'</h3><p class="result-explanation">✓ 正确答案：'+E(q?q.options[q.answer]:w.answer)+'</p><p>'+E(q?.explanation||w.explanation)+'</p>'+(q?'<button class="button subtle" data-knowledge-lesson="'+E(id)+'" data-practice-knowledge="'+E(q.conceptId)+'">查看对应讲解</button>':'')+'</section>';}).join(''));}

 function onAudioState(s){const providedAudio=s.mode==='audio'&&s.mediaSource!=='imported'&&window.PROVIDED_AUDIO_SOURCES?.[current?.id];$('#play').innerHTML=icon(s.playing?'pause':'play');$('#play').setAttribute('aria-label',s.playing?'暂停课文':'播放课文');$('#play').disabled=current?.source==='provided'&&!current?.textbook&&s.mode!=='audio';$('#play').title=$('#play').disabled?'本单元全文音频待接入，已收录单词可直接点读':'';$('#audio-mode').textContent=providedAudio?(providedAudio.label||'资料配套音频'):current?.source==='provided'&&!current?.textbook&&s.mode!=='audio'?'笔记文字版 · 全文音频待接入':s.mediaSource==='generated'?'美式合成音频 · 非原版录音':s.mode==='audio'?'已导入音频 · 本地资料':'系统语音 · 非原版录音';$('#audio-mode').title=providedAudio?[providedAudio.label,providedAudio.file].filter(Boolean).join(' · '):'';$('#voice').classList.toggle('hidden',s.mode==='audio');$('#voice-note').classList.toggle('hidden',s.mode!=='audio');$('#voice-note').textContent=providedAudio?(providedAudio.label||'资料配套音频'):s.mediaSource==='generated'?'美式合成':s.mode==='audio'?'文件原音':'';$('#seek').disabled=s.canSeek===false;const sourceLink=$('#audio-source-link'),sourcePage=providedAudio?.sourcePage;sourceLink.classList.toggle('hidden',!/^https?:\/\//.test(sourcePage||''));if(/^https?:\/\//.test(sourcePage||'')){sourceLink.href=sourcePage;sourceLink.title='查看音频来源';}else sourceLink.removeAttribute('href');}
 function onProgress(p){$('#current-time').textContent=formatTime(p.currentTime);$('#duration').textContent=(p.isEstimated?'约 ':'')+formatTime(p.duration);$('#seek').value=Math.round((p.progress||0)*1000);$('#seek').style.setProperty('--progress',`${(p.progress||0)*100}%`);}
 audio=new StudyAudio({onState:onAudioState,onProgress,onSentence:()=>readingView?.updatePlayback(),onError:message=>toast(message)});
 readingView=new ReadingView({getRoot:()=>$('#reader-content'),getLessonId:()=>current?.id,getAudioState:()=>audio?.state,getTopOffset:()=>{const toolbar=$('#reading-controls');return toolbar&&!toolbar.classList.contains('hidden')?Math.max(0,toolbar.getBoundingClientRect().bottom):0;},getBottomOffset:()=>{const tops=[$('.player'),$('.mls-bottom-nav')].filter(Boolean).map(node=>node.getBoundingClientRect()).filter(rect=>rect.height>0&&rect.top<innerHeight&&rect.bottom>0).map(rect=>rect.top);return tops.length?Math.max(0,innerHeight-Math.min(...tops)):0;},window});
 $('#show-translation').checked=data.settings.translation;$('#voice').value=data.settings.voice;$('#speed').value=String(data.settings.rate);audio.setVoice(data.settings.voice);audio.setRate(Number(data.settings.rate)||1);
 document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;
  if(b.dataset.book&&(view==='library'||view==='game')){selectedBook=Number(b.dataset.book);renderAll();return;}if(b.dataset.book){query='';$('#search').value='';const l=lessons.find(l=>l.book===Number(b.dataset.book));if(l)selectLesson(l.id);else{selectedBook=Number(b.dataset.book);current=null;outputContext=null;audio.stop();lessonVersion++;renderAll();}return;}
  if(b.dataset.lesson){selectLesson(b.dataset.lesson);return;}if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.tab){setTab(b.dataset.tab);return;}if(b.dataset.openTab){setTab(b.dataset.openTab);return;}
  if(b.dataset.retest){startRetest(b.dataset.retest);return;}
  if(b.dataset.practiceKnowledge){closeDialog();openKnowledge(b.dataset.knowledgeLesson||current.id,b.dataset.practiceKnowledge);return;}
  if(b.dataset.followup!==undefined&&practice.submitted){practice.followups=practice.followups||{};if(practice.followups[b.dataset.followup]===undefined)practice.followups[b.dataset.followup]=Number(b.dataset.followupAnswer);renderReader();return;}
  if(b.id==='retry-wrong-quiz'){const wrong=questions().filter((q,i)=>practice.answers[i]!==q.answer).map(q=>q.conceptId);practice={mode:practice.mode,answers:{},submitted:false,onlyConcepts:[...new Set(wrong)]};renderReader();return;}
  if(b.dataset.word){openWord(b.dataset.word,b);return;}if(b.dataset.speak){say(b.dataset.speak);return;}if(b.dataset.quizMode){practice={mode:b.dataset.quizMode,answers:{},submitted:false};renderReader();return;}
  if(b.dataset.question!==undefined&&!practice.submitted){practice.answers[b.dataset.question]=Number(b.dataset.answer);renderReader();return;}
  if(b.dataset.dictationSpeak!==undefined){say(current.vocabulary[Number(b.dataset.dictationSpeak)].word);return;}
  if(b.dataset.master){const v=data.words.find(v=>v.word===b.dataset.master);v.mastered=!v.mastered;persist();renderWords();return;}
  if(b.dataset.removeWord){data.words=data.words.filter(v=>v.word!==b.dataset.removeWord);persist();renderAll();toast('已移出生词本。');return;}if(b.dataset.review){review(b.dataset.review);return;}if(b.dataset.document){openDocument(b.dataset.document,Number(b.dataset.startSection)||0);return;}
  switch(b.id){case'play':if(audio.state.playing)audio.pause();else {try{await audio.play();}catch{}}break;case'loop':{const enabled=b.getAttribute('aria-pressed')!=='true';audio.setLoop(enabled);b.setAttribute('aria-pressed',String(enabled));b.classList.toggle('active',enabled);toast(enabled?'已开启本课循环':'已关闭循环');break;}case'previous-lesson':case'next-lesson':{const peers=lessons.filter(l=>l.book===current.book&&(!isPilotLesson(current)||isPilotLesson(l))),i=peers.findIndex(l=>l.id===current.id),l=peers[i+(b.id==='next-lesson'?1:-1)];if(l)selectLesson(l.id);break;}case'review-prerequisites':reviewPrerequisites();break;case'enroll-review':if(enrollLessonReview(current))toast('本课已加入每日复习，第一册和第二册的到期内容会一起安排。');break;case'complete-lesson':{const old=safeRecord(current.id);data.records[current.id]=StudyLearningProgress.markRead(old,!lessonProgress(current.id).read,Date.now());persist();renderReader();renderList();if(!old.completed)enrollLessonReview(current);mobileShell?.update({view,tab:activeTab,lesson:current});toast(old.completed?'已取消已读标记':'已记录读过，并加入每日复习；尚不代表掌握。');break;}case'close-word':hideWord();break;case'save-word':saveWord();break;case'submit-quiz':submitQuiz();break;case'retry-quiz':practice={mode:practice.mode,answers:{},submitted:false};renderReader();break;case'toggle-courses':{const list=$('#lesson-list');list.classList.toggle('collapsed');b.setAttribute('aria-expanded',String(!list.classList.contains('collapsed')));break;}case'tip-word':{setTab('reading');const w=$('.reader-content .word');if(w){openWord(w.dataset.word,w);w.focus();}break;}case'open-import':case'resources-import':openImport();break;case'open-resources':openResources();break;case'open-library':closeDialog();navigate('library');break;case'share-site':await shareSite();break;case'sharing-note':showSharingNote();break;case'close-dialog':case'cancel-import':closeDialog();break;case'confirm-import':await confirmImport();break;case'download-template':download('知新-课文导入模板.json',JSON.stringify({lessons:[{book:1,number:1,title:'My own lesson',subtitle:'我的课文',paragraphs:[{en:'A new day brings a new chance to learn.',zh:'新的一天带来新的学习机会。'}],vocabulary:[{word:'chance',phonetic:'/tʃɑːns/',pos:'n.',meaning:'机会',example:'Give it a chance.'}],usage:[{phrase:'a chance to do',meaning:'做某事的机会',note:'to 后接动词原形。',example:'I have a chance to learn.'}],quiz:[{type:'grammar',question:'She ___ English every day.',options:['study','studies','studying'],answer:1,explanation:'第三人称单数的一般现在时用 studies。'}]}]},null,2));break;case'export-words':download('知新-生词本.csv','\uFEFF单词,音标,词性,释义,例句,已掌握\n'+data.words.map(v=>[v.word,v.phonetic,v.pos,v.meaning,v.example,v.mastered?'是':'否'].map(x=>'"'+String(x||'').replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv;charset=utf-8');toast('生词本已导出。');break;case'export-backup':flushOutput();download('知新-学习备份.json',JSON.stringify({format:'zhixin-backup-v1',exportedAt:new Date().toISOString(),data},null,2));break;}
  if(b.dataset.action==='import')openImport();if(b.dataset.action==='resources')openResources();
 });
 document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value.trim().toLowerCase();renderList();if(view==='words')renderWords();if(view==='library')renderLibrary();}if(e.target.dataset.dictation!==undefined)practice.answers[e.target.dataset.dictation]=e.target.value;});
