 dailyReview=new ReviewPractice({container:$('#daily-review-view'),getLessons:()=>lessons,getState:()=>data.review,saveState:saveReviewState,escapeHTML:E,wordHTML,speak:say,toast,getCurrentLesson:()=>current,enrollCurrent:()=>enrollLessonReview(current),openLesson:selectLesson,backup:()=>download('知新-学习备份.json',JSON.stringify({format:'zhixin-backup-v1',exportedAt:new Date().toISOString(),data},null,2)),onChange:updateReviewCount});
 sentencePractice=new SentencePractice({getLesson:()=>outputContext||current,getLessons:()=>lessons,getRecords:()=>Object.fromEntries(Object.entries(data.records).map(([id,record])=>[id,{...record,completed:StudyReview.hasStudied(record)}])),getDrafts:()=>data.sentencePractice,saveDraft:(key,draft)=>{data.sentencePractice={...data.sentencePractice,[key]:StudySentences.sanitizeDraft(draft)};return persist();},grammarCheck:text=>window.StudyGrammar?StudyGrammar.check(text):null,escapeHTML:E,toast});
 batchPractice=new BatchSentencePractice({getLesson:()=>outputContext||current,getDraft:id=>Object.hasOwn(data.sentenceBatches,id)?data.sentenceBatches[id]:Object.hasOwn(data.sentenceBatch,id)?data.sentenceBatch[id]:null,saveDraft:(id,draft)=>{data.sentenceBatches={...data.sentenceBatches,[id]:StudySentenceBatch.sanitizeDraft(draft)};return persist();},grammarCheck:text=>window.StudyGrammar?StudyGrammar.check(text):null,sentenceCheck:options=>StudySentences.check(options),getGuidedText:guidedBatchText,escapeHTML:E,toast,copyText:text=>navigator.clipboard.writeText(text),downloadText:(name,text)=>download(name,text,'text/plain;charset=utf-8')});
 output=new OutputPractice({getLesson:()=>outputContext||current,saveRecord:saveOutputRecord,icon,escapeHTML:E,toast,speak:say,sentencePractice,batchPractice,canPracticeSentences:lesson=>lessons.some(item=>item.id===lesson?.id)});
