 document.addEventListener('click',event=>{if(event.target.closest?.('#retry-online-word'))lookupOnlineWord();});phrasePractice=new PhrasePractice({getLesson:()=>current,escapeHTML:E,wordHTML,toast,saveRecord:saveOutputRecord});textReader=new TextStudyLibrary({data:window.TEXT_LIBRARY||[],container:$('#library-view'),isActive:()=>view==='library',icon,escapeHTML:E,wordHTML,output,toast,beforeChange:flushOutput,onBack:renderLibrary,onLessonSelected:lesson=>{outputContext=lesson;}});game=new StudyGame({lessons:PILOT?window.LESSONS.filter(isPilotLesson):window.LESSONS,getData:()=>data.game,save:persist,openDialog,closeDialog,icon,escapeHTML:E,toast,onStudyKnowledge:openKnowledge,onChange:()=>{if(view==='game')renderGame();}});mobileShell=new MobileLearningShell({getLesson:()=>current,navigate,continueLesson:()=>{const l=lessons.find(x=>x.id===data.settings.pilotLesson&&isPilotLesson(x))||lessons.find(x=>x.book===2&&x.number===1);selectLesson(l.id);},onSelect:()=>mobileShell.focusReader(),getStatus:id=>lessonProgress(id).summary});hydrateIcons();if(current)selectLesson(current.id);else toast('课程资料尚未加载，请刷新页面。');if(storageWarning)toast('部分历史导入资料格式异常，可重新导入备份。');
